            status current;
            description
              "Incorporates a filter that has been configured
               separately.";
            leaf selection-filter-ref {
              type leafref {
                path "/sn:filters/yp:selection-filter/yp:filter-id";
                require-instance true;
                type string;
              }
              mandatory true;
              status current;
              description
                "References an existing selection filter that is to be
                 applied to the subscription.";
            }
          }
          case within-subscription {
            status current;
            description
              "Specifies the selection filter and where it originated
               from.  If the 'selection-filter-ref' is populated, the
               filter in the subscription came from the 'filters'
               container.  Otherwise, it is populated in-line as part
               of the subscription itself.";
            choice filter-spec {
              status current;
              description
                "The content filter specification for this request.";
              case datastore-subtree-filter {
                status current;
                anydata datastore-subtree-filter {
                  status current;
                  description
                    "This parameter identifies the portions of the
                     target datastore to retrieve.";
                  reference
                    "RFC 6241: Network Configuration Protocol (NETCONF),
                               Section 6";
                }
              }
              case datastore-xpath-filter {
                status current;
                leaf datastore-xpath-filter {
                  type string;
                  status current;
                  description
